import csv
import sys

# Check RFC 4180 compliance for clean_stops.csv
errors = []
with open('outputs/t05_clean_stops.csv', 'r', newline='') as f:
    reader = csv.reader(f)
    for i, row in enumerate(reader):
        if len(row) != 4:
            errors.append(f'Row {i+1} has {len(row)} fields, expected 4')

        # Check if any field needs quoting
        for j, field in enumerate(row):
            if ',' in field or '\"' in field or '\n' in field:
                # Check if already quoted
                if not (field.startswith('\"') and field.endswith('\"')):
                    errors.append(f'Row {i+1}, field {j+1} contains special chars but not quoted: {repr(field)}')

if errors:
    print('RFC 4180 errors in clean_stops.csv:')
    for e in errors:
        print(e)
else:
    print('clean_stops.csv appears RFC 4180 compliant')

# Check RFC 4180 compliance for clean_stop_times.csv
errors2 = []
with open('outputs/t05_clean_stop_times.csv', 'r', newline='') as f:
    reader = csv.reader(f)
    for i, row in enumerate(reader):
        if len(row) != 5:
            errors2.append(f'Row {i+1} has {len(row)} fields, expected 5')

if errors2:
    print('RFC 4180 errors in clean_stop_times.csv:')
    for e in errors2:
        print(e)
else:
    print('clean_stop_times.csv appears RFC 4180 compliant')
""}

